108|export function PanelsModal({
109|  ch,
110|  chapterTitle,
111|  panels,
112|  onClose,
113|  onOpenArt,
114|}: {
115|  ch: number;
116|  chapterTitle: string;
117|  panels: ChapterPanel[];
118|  onClose: () => void;
119|  onOpenArt: (src: string, caption: string, opener: HTMLElement | null) => void;
120|}) {
121|  const chapterLabel = `Chapter ${ch}, ${chapterTitle}`;
122|  const closeRef = useRef<HTMLButtonElement | null>(null);
123|  const boxRef = useRef<HTMLDivElement | null>(null);
124|  // Session cache first, bundled art next, placeholder last.
125|  const [resolved] = useState<ResolvedPanel[]>(() =>
126|    panels.map((p) => ({ ...p, url: getCachedScenePicture(p.sceneId)?.url ?? p.art })),
127|  );
128|
129|  useEffect(() => {
130|    const opener = document.activeElement instanceof HTMLElement ? document.activeElement : null;
131|    closeRef.current?.focus();
132|    const onKey = (event: KeyboardEvent) => {
133|      if (event.key === "Escape") {
134|        // The shared lightbox sits above the modal and closes itself.
135|        if (document.querySelector(".lightbox")) return;
136|        event.stopPropagation();
137|        onClose();
138|        return;
139|      }
140|      if (event.key !== "Tab" || !boxRef.current) return;
141|      const items = [...boxRef.current.querySelectorAll<HTMLElement>("button, [href], [tabindex]:not([tabindex='-1'])")].filter(
142|        (el) => !el.hasAttribute("disabled"),
143|      );
144|      if (items.length === 0) return;
145|      const first = items[0] as HTMLElement;
146|      const last = items[items.length - 1] as HTMLElement;
147|      if (event.shiftKey && document.activeElement === first) {
148|        event.preventDefault();
149|        last.focus();
150|      } else if (!event.shiftKey && document.activeElement === last) {
151|        event.preventDefault();
152|        first.focus();
153|      }
154|    };
155|    document.addEventListener("keydown", onKey, true);
156|    return () => {
157|      document.removeEventListener("keydown", onKey, true);
158|      opener?.focus?.();
159|    };
160|  }, [onClose]);
161|
162|  return (
163|    <div className="panels-modal" role="dialog" aria-modal="true" aria-label={chapterLabel}>
164|      <div ref={boxRef} className="panels-box">
165|        <button ref={closeRef} type="button" className="panels-x" onClick={onClose} aria-label="Close">
