83|export function Divider() {
84|  const [width, setWidth] = useState(defaultSplit);
85|  const [viewport, setViewport] = useState(1280);
86|  const ref = useRef<HTMLDivElement | null>(null);
87|
88|  useEffect(() => {
89|    const measure = () => setViewport(window.innerWidth);
90|    measure();
91|    window.addEventListener("resize", measure);
92|    try {
93|      const saved = Number(window.localStorage.getItem(SPLIT_KEY));
94|      if (Number.isFinite(saved) && saved > 0) {
95|        setWidth(clampSplitWidth(saved, window.innerWidth));
96|        return () => window.removeEventListener("resize", measure);
97|      }
98|    } catch {
99|      // Fresh default below.
100|    }
101|    setWidth(defaultSplit());
102|    return () => window.removeEventListener("resize", measure);
103|  }, []);
104|
105|  useEffect(() => {
106|    document.documentElement.style.setProperty("--pane-w", `${width}px`);
107|  }, [width]);
108|
109|  function commit(next: number) {
110|    const clamped = clampSplitWidth(next, window.innerWidth);
111|    setWidth(clamped);
112|    try {
113|      window.localStorage.setItem(SPLIT_KEY, String(clamped));
114|    } catch {
115|      // Dragging still works for the session.
116|    }
117|  }
118|
119|  return (
120|    <div
121|      ref={ref}
122|      className="pane-divider"
123|      role="separator"
124|      aria-orientation="vertical"
125|      aria-label="Resize image pane"
126|      aria-valuemin={SPLIT_MIN_PX}
127|      aria-valuemax={clampSplitWidth(Number.MAX_SAFE_INTEGER, viewport)}
128|      aria-valuenow={width}
129|      tabIndex={0}
130|      title="Drag to resize, double-click to reset"
131|      onDoubleClick={() => commit(defaultSplit())}
132|      onKeyDown={(e) => {
133|        if (e.key === "ArrowLeft") {
134|          e.preventDefault();
135|          commit(width - 16);
136|        } else if (e.key === "ArrowRight") {
137|          e.preventDefault();
138|          commit(width + 16);
139|        }
140|      }}
141|      onPointerDown={(e) => {
142|        (e.target as HTMLElement).setPointerCapture?.(e.pointerId);
143|        const move = (ev: PointerEvent) => {
144|          const grid = ref.current?.parentElement?.getBoundingClientRect();
145|          if (grid) commit(ev.clientX - grid.left);
146|        };
147|        const up = () => {
148|          window.removeEventListener("pointermove", move);
149|          window.removeEventListener("pointerup", up);
150|        };
151|        window.addEventListener("pointermove", move);
152|        window.addEventListener("pointerup", up);
153|      }}
154|    >
155|      <span className="grip" aria-hidden="true">
156|        |
157|      </span>
158|    </div>
159|  );
